          "campaignId",
          "expectedListUpdatedAt",
          "expectedCampaignUpdatedAt",
          "expectedTotal",
          "expectedTargetCount",
          "excludeCompanies",
          "expectedRemaining",
          "expectedRemainingTargetCount",
          "idempotencyKey",
          "apply",
